@Serializable
data class AppSettings(val theme: Theme = Theme.System, val fontScale: Float = 1f, val wifiOnly: Boolean = true)

object AppSettingsSerializer : Serializer<AppSettings> {
    override val defaultValue = AppSettings()
    override suspend fun readFrom(input: InputStream): AppSettings =
        try { Json.decodeFromString(input.readBytes().decodeToString()) }
        catch (e: SerializationException) { throw CorruptionException("Bad settings", e) }
    override suspend fun writeTo(t: AppSettings, output: OutputStream) =
        output.write(Json.encodeToString(t).encodeToByteArray())
}

val Context.appSettings by dataStore(
    fileName = "app_settings.json",
    serializer = AppSettingsSerializer,
    corruptionHandler = ReplaceFileCorruptionHandler { AppSettings() },
)

suspend fun setWifiOnly(ctx: Context, on: Boolean) = ctx.appSettings.updateData { it.copy(wifiOnly = on) }

@Entity(tableName = "tasks", indices = [Index("done"), Index("title")])
data class TaskEntity(
    @PrimaryKey val id: String = UUID.randomUUID().toString(),
    val title: String,
    val done: Boolean = false,
    val createdAt: Long = System.currentTimeMillis(),
)

@Dao
interface TaskDao {
    @Query("SELECT * FROM tasks WHERE done = :done ORDER BY createdAt DESC")
    fun observe(done: Boolean): Flow<List<TaskEntity>>

    @Query("SELECT COUNT(*) FROM tasks WHERE done = 0")
    fun openCount(): Flow<Int>

    @Upsert suspend fun upsert(task: TaskEntity)
    @Delete suspend fun delete(task: TaskEntity)
}

