@RunWith(AndroidJUnit4::class)
class TaskDaoTest {
    private lateinit var db: AppDatabase
    private lateinit var dao: TaskDao

    @Before fun setUp() {
        db = Room.inMemoryDatabaseBuilder(ApplicationProvider.getApplicationContext(), AppDatabase::class.java).build()
        dao = db.tasks()
    }
    @After fun tearDown() = db.close()

    @Test fun upsertReplacesTheSameId() = runTest {
        dao.upsert(TaskEntity(id = "1", title = "Buy milk"))
        dao.upsert(TaskEntity(id = "1", title = "Buy oat milk"))
        assertEquals(listOf("Buy oat milk"), dao.observe(done = false).first().map { it.title })
    }

    @Test fun openCountUpdatesAfterInsert() = runTest {
        dao.openCount().test {
            assertEquals(0, awaitItem())
            dao.upsert(TaskEntity(title = "Call mom"))
            assertEquals(1, awaitItem())
            cancelAndIgnoreRemainingEvents()
        }
    }
}

