@RenameColumn(tableName = "notes", fromColumnName = "text", toColumnName = "body")
class Rename2To3 : AutoMigrationSpec

// Changing a column type: create, copy, drop, rename.
val MIGRATION_3_4 = object : Migration(3, 4) {
    override fun migrate(db: SupportSQLiteDatabase) {
        db.execSQL("CREATE TABLE notes_new (id TEXT NOT NULL PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 0)")
        db.execSQL("INSERT INTO notes_new (id, title, body, priority) SELECT id, title, body, CAST(priority AS INTEGER) FROM notes")
        db.execSQL("DROP TABLE notes")
        db.execSQL("ALTER TABLE notes_new RENAME TO notes")
    }
}

@RunWith(AndroidJUnit4::class)
class MigrationTest {
    private val dbName = "migration-test"

    @get:Rule
    val helper = MigrationTestHelper(
        InstrumentationRegistry.getInstrumentation(),
        AppDatabase::class.java,
        listOf(Rename2To3()),                     // auto-migration specs
    )

    @Test fun from1To4KeepsNotes() {
        helper.createDatabase(dbName, 1).use { db ->
            db.execSQL("INSERT INTO notes (id, title, text, priority) VALUES ('n1', 'Groceries', 'Milk', '2')")
            db.execSQL("INSERT INTO notes (id, title, text, priority) VALUES ('n2', 'Empty', '', 'high')")
        }
        val db = helper.runMigrationsAndValidate(dbName, 4, true, MIGRATION_3_4)
        db.query("SELECT body, priority FROM notes ORDER BY id").use { c ->
            c.moveToFirst(); assertEquals("Milk", c.getString(0)); assertEquals(2, c.getInt(1))
            c.moveToNext(); assertEquals(0, c.getInt(1))     // "high" could not convert
        }
    }
}

suspend fun saveToGallery(context: Context, bitmap: Bitmap, name: String): Uri? = withContext(Dispatchers.IO) {
    val values = ContentValues().apply {
        put(MediaStore.Images.Media.DISPLAY_NAME, "$name.jpg")
        put(MediaStore.Images.Media.MIME_TYPE, "image/jpeg")
        put(MediaStore.Images.Media.RELATIVE_PATH, Environment.DIRECTORY_PICTURES + "/Receipts")
        put(MediaStore.Images.Media.IS_PENDING, 1)                 // hidden until written
    }
    val resolver = context.contentResolver
    val uri = resolver.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, values) ?: return@withContext null
    resolver.openOutputStream(uri)?.use { bitmap.compress(Bitmap.CompressFormat.JPEG, 90, it) }
    values.clear(); values.put(MediaStore.Images.Media.IS_PENDING, 0)
    resolver.update(uri, values, null, null)
    uri
}

fun trimCache(context: Context, maxBytes: Long = 50L * 1024 * 1024) {
    val files = context.cacheDir.listFiles().orEmpty().sortedBy { it.lastModified() }
    var total = files.sumOf { it.length() }
    for (f in files) { if (total <= maxBytes) break; total -= f.length(); f.delete() }
}

