class UploadPhotoWorker(ctx: Context, params: WorkerParameters, private val repo: PhotoRepository) :
    CoroutineWorker(ctx, params) {

    override suspend fun doWork(): Result {
        val id = inputData.getString(KEY_ID) ?: return Result.failure()
        return try {
            repo.upload(id)                              // server dedupes by id
            Result.success()
        } catch (e: IOException) {
            if (runAttemptCount >= 4) Result.failure(workDataOf("error" to e.message)) else Result.retry()
        }
    }
    companion object { const val KEY_ID = "photo_id" }
}

fun enqueuePhotoUpload(wm: WorkManager, photoId: String) {
    val request = OneTimeWorkRequestBuilder<UploadPhotoWorker>()
        .setInputData(workDataOf(UploadPhotoWorker.KEY_ID to photoId))
        .setConstraints(Constraints(requiredNetworkType = NetworkType.UNMETERED, requiresBatteryNotLow = true))
        .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
        .build()
    wm.enqueueUniqueWork("upload-$photoId", ExistingWorkPolicy.KEEP, request)
}

fun scheduleDailyCleanup(wm: WorkManager) {
    val daily = PeriodicWorkRequestBuilder<CleanupWorker>(1, TimeUnit.DAYS)
        .setConstraints(Constraints(requiresCharging = true))
        .build()
    wm.enqueueUniquePeriodicWork("daily-cleanup", ExistingPeriodicWorkPolicy.UPDATE, daily)
}

fun uploadAlbum(wm: WorkManager, photoIds: List<String>) {
    val compress = photoIds.map { id ->
        OneTimeWorkRequestBuilder<CompressWorker>().setInputData(workDataOf("id" to id)).build()
    }
    wm.beginUniqueWork("album", ExistingWorkPolicy.KEEP, compress)
        .then(OneTimeWorkRequestBuilder<UploadAlbumWorker>().build())
        .then(OneTimeWorkRequestBuilder<CleanupWorker>().build())
        .enqueue()
}

