class ArticleRepository(private val dao: ArticleDao, private val api: NewsApi, private val clock: Clock) {
    fun observe(): Flow<List<Article>> = dao.observeAll().map { it.map(ArticleEntity::toDomain) }

    suspend fun refreshIfStale(maxAge: Duration = 15.minutes): Result<Unit> {
        val last = dao.lastUpdated() ?: 0L
        if (clock.millis() - last < maxAge.inWholeMilliseconds) return Result.success(Unit)
        return runCatchingNetwork {
            val fresh = api.latest()
            dao.replaceAll(fresh.map { it.toEntity(updatedAt = clock.millis()) })   // @Transaction
        }
    }
}

