class SyncWorker(ctx: Context, p: WorkerParameters, private val db: AppDatabase, private val api: TaskApi) :
    CoroutineWorker(ctx, p) {

    override suspend fun doWork(): Result = try {
        for (entry in db.outbox().pending()) {                         // oldest first
            when (val r = api.apply(entry.toRequest(idempotencyKey = entry.id))) {
                is ApiResult.Ok -> db.outbox().delete(entry.id)
                is ApiResult.Rejected -> db.withTransaction {
                    db.outbox().delete(entry.id)
                    db.tasks().markSyncFailed(entry.entityId, r.reason)
                }
            }
        }
        val changes = api.changesSince(db.syncState().token())
        db.withTransaction {
            changes.updated.forEach { remote ->
                val local = db.tasks().byId(remote.id)
                if (local == null || !local.pending || remote.updatedAt > local.updatedAt) db.tasks().upsert(remote.toEntity())
            }
            db.tasks().deleteByIds(changes.deletedIds)
            db.syncState().save(changes.nextToken)
        }
        Result.success()
    } catch (e: IOException) { Result.retry() }
}
